445	+#pragma once
446	+
447	+// The per-plate summary of what OrcaSlicer warned about in a slice: how many
448	+// warnings and the one to read first. Plain data, so the rule can be tested
449	+// without the application.
450	+
451	+#include "Workspace.hpp"
452	+
453	+#include <algorithm>
454	+#include <set>
455	+#include <vector>
456	+
457	+namespace Slic3r::GUI::JusPrin::Workspace {
458	+
459	+// The summary of `findings`, numbered `sequence`; nothing when there are none.
460	+inline std::optional<SliceWarnings> summarize_slice_warnings(const std::vector<SliceWarningFinding>& findings,
461	+                                                             ProjectSessionId session, std::uint64_t sequence)
462	+{
463	+    if (findings.empty())
464	+        return std::nullopt;
465	+    // Critical first, then one the person has not ignored; otherwise
466	+    // OrcaSlicer's order.
467	+    const auto rank = [](const SliceWarningFinding& finding) { return (finding.critical ? 0 : 2) + (finding.ignored ? 1 : 0); };
468	+    const auto top  = std::min_element(findings.begin(), findings.end(),
469	+                                       [&rank](const SliceWarningFinding& a, const SliceWarningFinding& b) { return rank(a) < rank(b); });
470	+    SliceWarnings summary;
471	+    summary.count       = findings.size();
472	+    summary.ignored     = std::size_t(std::count_if(findings.begin(), findings.end(),
473	+                                                    [](const SliceWarningFinding& finding) { return finding.ignored; }));
474	+    summary.severity    = top->critical ? "critical" : "warning";
475	+    summary.message     = top->message;
476	+    summary.setting     = top->setting;
477	+    summary.code        = top->code;
478	+    summary.object_name = top->object_name;
479	+    if (top->object != 0)
480	+        summary.object = ObjectId(session, top->object);
481	+    summary.sequence = sequence;
482	+    return summary;
483	+}
484	+
485	+// Whether `findings` holds a warning `known` (the ids of the plate's last
486	+// record) does not: the moment a reader has something new to be told.
487	+inline bool has_new_slice_warning(const std::vector<SliceWarningFinding>& findings, const std::set<std::string>& known)
488	+{
489	+    return std::any_of(findings.begin(), findings.end(),
490	+                       [&known](const SliceWarningFinding& finding) { return known.count(finding.id) == 0; });
491	+}
492	+
